buildSrc/build.gradle.kts
buildSrc/settings.gradle.kts
=== settings ===
rootProject.name = "menden-cms"

pluginManagement {
    repositories {
        // io.swcode.* plugins are resolved from the public, read-only S3 maven repo — no credentials required.
        maven {
            url = uri("https://urbo-maven.s3.eu-central-1.amazonaws.com/releases")
            mavenContent {
                includeGroupByRegex("io\\.swcode.*")
            }
        }
        mavenCentral()
        gradlePluginPortal()
    }
}

plugins {
    // Apply the foojay-resolver plugin to allow automatic download of JDKs
    id("org.gradle.toolchains.foojay-resolver-convention") version "1.0.0"
    id("de.fayard.refreshVersions") version "0.60.6"
}

refreshVersions {
    rejectVersionIf {
        candidate.stabilityLevel.isLessStableThan(de.fayard.refreshVersions.core.StabilityLevel.Stable)
    }
}

dependencyResolutionManagement {
    repositories {
        // io.swcode.* dependencies are resolved from the public, read-only S3 maven repo — no credentials required.
        maven {
            url = uri("https://urbo-maven.s3.eu-central-1.amazonaws.com/releases")
            mavenContent {
                includeGroupByRegex("io\\.swcode.*")
            }
        }
        mavenCentral()
    }

    versionCatalogs {
        create("urbocatalog") {
            from("io.swcode.urbo:urbo-catalog:2.0.194")
        }
    }
}

include("menden-app")
include("menden-client")
include("erlebnis-stadt-experience")
include("menden-experience-adapter")
